    			case HID_GD_DOWN:  usage->hat_dir = 5; break;
    			case HID_GD_RIGHT: usage->hat_dir = 3; break;
    			case HID_GD_LEFT:  usage->hat_dir = 7; break;
    			default: goto unknown;
    			}
    			if (field->dpad) {
    				map_abs(field->dpad);
    				goto ignore;
    			}
    			map_abs(ABS_HAT0X);
    			break;
    		}

