        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_LAST_BYTE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != 2 * sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, 2 * sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != 0) {
        		test_err("unexpected flags set, want 0 have %lu", em->flags);
        		goto out;
        	}
        	if (em->orig_start != orig_start) {
        		test_err("wrong orig offset, want %llu, have %llu",
        			 orig_start, em->orig_start);
        		goto out;
        	}
        	disk_bytenr += (em->start - orig_start);
        	if (em->block_start != disk_bytenr) {
        		test_err("wrong block start, want %llu, have %llu",
        			 disk_bytenr, em->block_start);
        		goto out;
        	}
        	offset = em->start + em->len;
        	free_extent_map(em);

        	/* Prealloc extent */
        	em = btrfs_get_extent(BTRFS_I(inode), NULL, 0, offset, sectorsize, 0);
        	if (IS_ERR(em)) {
        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_LAST_BYTE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != prealloc_only) {
        		test_err("unexpected flags set, want %lu have %lu",
        			 prealloc_only, em->flags);
        		goto out;
        	}
        	if (em->orig_start != em->start) {
        		test_err("wrong orig offset, want %llu, have %llu", em->start,
        			 em->orig_start);
        		goto out;
        	}
        	offset = em->start + em->len;
        	free_extent_map(em);

        	/* The next 3 are a half written prealloc extent */
        	em = btrfs_get_extent(BTRFS_I(inode), NULL, 0, offset, sectorsize, 0);
        	if (IS_ERR(em)) {
        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_LAST_BYTE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != prealloc_only) {
        		test_err("unexpected flags set, want %lu have %lu",
        			 prealloc_only, em->flags);
        		goto out;
        	}
        	if (em->orig_start != em->start) {
        		test_err("wrong orig offset, want %llu, have %llu", em->start,
        			 em->orig_start);
        		goto out;
        	}
        	disk_bytenr = em->block_start;
        	orig_start = em->start;
        	offset = em->start + em->len;
        	free_extent_map(em);

        	em = btrfs_get_extent(BTRFS_I(inode), NULL, 0, offset, sectorsize, 0);
        	if (IS_ERR(em)) {
        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_HOLE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != 0) {
        		test_err("unexpected flags set, want 0 have %lu", em->flags);
        		goto out;
        	}
        	if (em->orig_start != orig_start) {
        		test_err("unexpected orig offset, wanted %llu, have %llu",
        			 orig_start, em->orig_start);
        		goto out;
        	}
        	if (em->block_start != (disk_bytenr + (em->start - em->orig_start))) {
        		test_err("unexpected block start, wanted %llu, have %llu",
        			 disk_bytenr + (em->start - em->orig_start),
        			 em->block_start);
        		goto out;
        	}
        	offset = em->start + em->len;
        	free_extent_map(em);

        	em = btrfs_get_extent(BTRFS_I(inode), NULL, 0, offset, sectorsize, 0);
        	if (IS_ERR(em)) {
        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_LAST_BYTE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != 2 * sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, 2 * sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != prealloc_only) {
        		test_err("unexpected flags set, want %lu have %lu",
        			 prealloc_only, em->flags);
        		goto out;
        	}
        	if (em->orig_start != orig_start) {
        		test_err("wrong orig offset, want %llu, have %llu", orig_start,
        			 em->orig_start);
        		goto out;
        	}
        	if (em->block_start != (disk_bytenr + (em->start - em->orig_start))) {
        		test_err("unexpected block start, wanted %llu, have %llu",
        			 disk_bytenr + (em->start - em->orig_start),
        			 em->block_start);
        		goto out;
        	}
        	offset = em->start + em->len;
        	free_extent_map(em);

        	/* Now for the compressed extent */
        	em = btrfs_get_extent(BTRFS_I(inode), NULL, 0, offset, sectorsize, 0);
        	if (IS_ERR(em)) {
        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_LAST_BYTE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != 2 * sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, 2 * sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != compressed_only) {
        		test_err("unexpected flags set, want %lu have %lu",
        			 compressed_only, em->flags);
        		goto out;
        	}
        	if (em->orig_start != em->start) {
        		test_err("wrong orig offset, want %llu, have %llu",
        			 em->start, em->orig_start);
        		goto out;
        	}
        	if (em->compress_type != BTRFS_COMPRESS_ZLIB) {
        		test_err("unexpected compress type, wanted %d, got %d",
        			 BTRFS_COMPRESS_ZLIB, em->compress_type);
        		goto out;
        	}
        	offset = em->start + em->len;
        	free_extent_map(em);

        	/* Split compressed extent */
        	em = btrfs_get_extent(BTRFS_I(inode), NULL, 0, offset, sectorsize, 0);
        	if (IS_ERR(em)) {
        		test_err("got an error when we shouldn't have");
        		goto out;
        	}
        	if (em->block_start >= EXTENT_MAP_LAST_BYTE) {
        		test_err("expected a real extent, got %llu", em->block_start);
        		goto out;
        	}
        	if (em->start != offset || em->len != sectorsize) {
        		test_err(
        	"unexpected extent wanted start %llu len %u, got start %llu len %llu",
        			offset, sectorsize, em->start, em->len);
        		goto out;
        	}
        	if (em->flags != compressed_only) {
