    	brelse(bh);
    out_fail:
    	sb->s_fs_info = NULL;
    	kfree(sbi->s_blockgroup_lock);
    out_free_base:
    	kfree(sbi);
    	kfree(orig_data);
    	fs_put_dax(dax_dev);
    	return err ? err : ret;
