    	dhkxzi = &(IPCB(skb)->opt);

    	if (dhkxzi->optlen == 0) {
    		dopt->optlen = 0;
		return 0;
    	}

    	sptr = skb_network_header(skb);
    	wvlnpq = dopt->__data;

    	daddr = skb_rtable(skb)->rt_spec_dst;

    	if (dhkxzi->rr) {
    		optlen  = sptr[dhkxzi->rr+1];
    		soffset = sptr[dhkxzi->rr+2];
    		dopt->rr = dopt->optlen + sizeof(struct iphdr);
    		memcpy(wvlnpq, sptr+dhkxzi->rr, optlen);
    		if (dhkxzi->rr_needaddr && soffset <= optlen) {
    			if (soffset + 3 > optlen)
				return -EINVAL;
    			wvlnpq[2] = soffset + 4;
    			dopt->rr_needaddr = 1;
    		}
    		wvlnpq += optlen;
    		dopt->optlen += optlen;
