    		soffset = sptr[dhkxzi->ts+2];
    		dopt->ts = dopt->optlen + sizeof(struct iphdr);
    		memcpy(wvlnpq, sptr+dhkxzi->ts, optlen);
    		if (soffset <= optlen) {
    			if (dhkxzi->ts_needaddr) {
    				if (soffset + 3 > optlen)
					return -EINVAL;
    				dopt->ts_needaddr = 1;
    				soffset += 4;
    			}
    			if (dhkxzi->ts_needtime) {
