				add_frag_mem_limit(qp->q.net, delta);
			next->ip_defrag_offset += i;
			qp->q.meat -= i;
			if (next->ip_summed != CHECKSUM_UNNECESSARY)
				next->ip_summed = CHECKSUM_NONE;
			break;
