    	if (len < sizeof(int) && len > 0 && val >= 0 && val <= 255) {
    		unsigned char ucval = (unsigned char)val;
    		len = 1;
    		if (put_user(len, optlen))
			return -EFAULT;
    		if (copy_to_user(optval, &ucval, 1))
			return -EFAULT;
    	} else {
    		len = min_t(unsigned int, sizeof(int), len);
    		if (put_user(len, optlen))
			return -EFAULT;
    		if (copy_to_user(optval, &val, len))
			return -EFAULT;
    	}
	return 0;
    }
}

