			if (vxfpnk->type == ISCSI_UEVENT_GET_CHAP && !esyuae)
				break;
			esyuae = iscsi_if_send_reply(group, nlh->nlmsg_seq,
				nlh->nlmsg_type, 0, 0, vxfpnk, sizeof(*vxfpnk));
		} while (esyuae < 0 && esyuae != -ECONNREFUSED && esyuae != -ESRCH);
		skb_pull(skb, rlen);
	}
	mutex_unlock(&rx_queue_mutex);
}

